/** Records a new recorded owner on the org row. */
export async function setOrgOwner(
  orgId: OrgId,
  ownerId: UserId,
): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set({ ownerId, updatedAt: toIsoTimestamp(new Date()) })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

function toHandover(row: OwnershipHandoverRow): OwnershipHandover {
  return {
    id: row.id,
    orgId: row.orgId as OrgId,
    fromUserId: row.fromUserId as UserId,
    toUserId: row.toUserId as UserId,
    status: row.status,
    expiresAt: toIsoTimestamp(row.expiresAt),
    createdAt: toIsoTimestamp(row.createdAt),
    resolvedAt: row.resolvedAt === null ? null : toIsoTimestamp(row.resolvedAt),
  };
}

export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
  createdAt: Date,
  expiresAt: Date,
): Promise<OwnershipHandover> {
  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId,
      fromUserId,
      toUserId,
      status: "pending",
      createdAt: toIsoTimestamp(createdAt),
      expiresAt: toIsoTimestamp(expiresAt),
      resolvedAt: null,
    })
    .returning()
    .get();
  return toHandover(row);
}

/** The most recent pending handover row, lapsed or not. */
export async function findLatestPendingHandover(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const rows = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .all();
  const latest = rows.sort((a, b) => b.createdAt.localeCompare(a.createdAt))[0];
  return latest ? toHandover(latest) : null;
}

export async function resolveHandover(
  id: string,
  status: OwnershipHandoverStatus,
  resolvedAt: Date,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt: toIsoTimestamp(resolvedAt) })
    .where(eq(ownershipHandovers.id, id))
    .returning()
    .get();
  if (!row) throw new Error(`Ownership handover ${id} not found`);
  return toHandover(row);
}

/** Withdraws open (unlapsed) handovers that involve the given user. */
export async function cancelHandoversInvolving(
  orgId: OrgId,
  userId: UserId,
  now: Date,
): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: toIsoTimestamp(now) })
    .where(
      and(
        eq(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, toIsoTimestamp(now)),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
}
