p="src/server/services/organization-service.ts"
s=open(p).read()
s=s.replace('import { emit } from "@/lib/event-bus";','import { emit } from "@/lib/event-bus";\nimport { OwnershipHandoverError } from "@/lib/errors";\nimport { PermissionDeniedError } from "@/lib/permissions";')
s=s.replace('import { record } from "./activity-service";','import { record } from "./activity-service";\nimport { notify } from "./notification-service";')
s=s.replace('import { envelope, orgResource, requireFound } from "./_support";','import {\n  actorEnvelope,\n  envelope,\n  NotFoundError,\n  orgResource,\n  requireFound,\n} from "./_support";')
s=s.replace('import type { Organization, OrganizationSummary } from "@/types/organization";','import type {\n  Organization,\n  OrganizationSummary,\n  OwnershipHandover,\n} from "@/types/organization";')
s+='''
/** How long an ownership offer stays open. */
const HANDOVER_TTL_MS = 7 * 24 * 60 * 60 * 1000;

function isLapsed(handover: OwnershipHandover, now: Date): boolean {
  return now.getTime() >= new Date(handover.expiresAt).getTime();
}

async function loadOrg(orgId: OrgId): Promise<Organization> {
  return requireFound(await orgRepo.findOrgById(orgId), "Organization", orgId);
}

/** Only the recorded owner — not any holder of the owner role — may offer or withdraw. */
function assertRecordedOwner(actor: Actor, org: Organization): void {
  if (org.ownerId !== actor.userId) {
    throw new PermissionDeniedError("org:manage_billing", {
      allowed: false,
      action: "org:manage_billing",
      resourceKind: "organization",
      reason: "denied_by_role",
    });
  }
}

async function findOpenHandover(
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover | null> {
  const pending = await orgRepo.findLatestPendingHandover(orgId);
  return pending && !isLapsed(pending, now) ? pending : null;
}

/** The offered member's pending handover, refusing lapsed or foreign ones. */
async function requireOfferedHandover(
  actor: Actor,
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover> {
  const pending = await orgRepo.findLatestPendingHandover(orgId);
  if (!pending || pending.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (isLapsed(pending, now)) throw new OwnershipHandoverError("expired");
  return pending;
}

export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = await loadOrg(orgId);
  assertRecordedOwner(actor, org);

  if (toUserId === actor.userId) throw new OwnershipHandoverError("self");

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = new Date();
  if (await findOpenHandover(orgId, now)) {
    throw new OwnershipHandoverError("pending_exists");
  }

  const handover = await orgRepo.insertHandover(
    orgId,
    actor.userId,
    toUserId,
    now,
    new Date(now.getTime() + HANDOVER_TTL_MS),
  );

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You have been offered workspace ownership",
    body: `${org.name} is offered to you; accept to become its owner`,
    href: "/settings/general",
    actorId: actor.userId,
  });

  return handover;
}

export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);
  const now = new Date();
  const handover = await requireOfferedHandover(actor, orgId, now);
  const org = await loadOrg(orgId);
  const previousOwnerId = org.ownerId;

  const incoming = await memberRepo.findMember(orgId, actor.userId);
  if (!incoming || incoming.status !== "active") {
    throw new NotFoundError("Member", actor.userId);
  }

  // Promote first so the workspace is never without an owner.
  if (incoming.role !== "owner") {
    const promoted = await memberRepo.updateMemberRole(orgId, incoming.id, "owner");
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: promoted.id,
      from: incoming.role,
      to: promoted.role,
    });
  }

  const updated = await orgRepo.setOrgOwner(orgId, actor.userId);
  await orgRepo.resolveHandover(handover.id, "accepted", now);

  if (previousOwnerId !== actor.userId) {
    const outgoing = await memberRepo.findMember(orgId, previousOwnerId);
    if (outgoing && outgoing.role === "owner") {
      const demoted = await memberRepo.updateMemberRole(orgId, outgoing.id, "admin");
      await emit("member.role_changed", {
        ...actorEnvelope(actor),
        memberId: demoted.id,
        from: outgoing.role,
        to: demoted.role,
      });
    }
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: previousOwnerId,
    toUserId: actor.userId,
  });

  return updated;
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const now = new Date();
  const handover = await requireOfferedHandover(actor, orgId, now);
  return orgRepo.resolveHandover(handover.id, "declined", now);
}

export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const org = await loadOrg(orgId);
  assertRecordedOwner(actor, org);

  const now = new Date();
  const handover = await findOpenHandover(orgId, now);
  if (!handover) throw new OwnershipHandoverError("nothing_pending");
  return orgRepo.resolveHandover(handover.id, "canceled", now);
}

export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));
  return findOpenHandover(orgId, new Date());
}
'''
